const d = $json;
return [{json:{
  ...d,
  sessionId: d.chatId,
  contextText: `Student ID: ${d.studentId}
Student: ${d.studentName || 'Student'}
Class/Batch: ${d.className || d.batchName || 'Unknown'}
Course: ${d.courseName || 'Unknown'}
Teacher: ${d.teacherName || 'Unknown'}
Course Duration: ${d.courseDuration || 'Unknown'}
End Date: ${d.endDate || 'Unknown'}`
}}];

let base = {};
try { base = $('Build Session Context').first()?.json || {}; } catch(e) {}
if (!base.messageText) {
  try { base = $('Normalize Telegram Message').first()?.json || {}; } catch(e) {}
}

const text = String(base.messageText || '').trim();

// 1. Security Violations / Injections / Exfiltration
const isSecurityAttack = /\b(ignore\s+(?:all\s+)?(?:previous\s+)?instructions|show\s+(?:your\s+)?(?:system|hidden)\s*prompt|system\s*prompt|give\s+me\s+(?:the\s+)?api\s*key|api\s*key|lms_service_key|telegram\s*token|show\s+(?:all\s+)?environment|database\s*password|show\s+(?:all\s+)?students?|another\s+student|student\s+(?:123|999)|student_id\s*=\s*\d+|my\s+friend\s+is\s+student|pretend\s+my\s+fees\s+are\s+zero)\b/i.test(text);

// 2. Leave & Absence requests
const isLeave = /\b(will\s+be\s+absent|apply(?:ing)?\s+for\s+leave|sick\s+leave|medical\s+leave|take\s+leave|leave\s+application|absent\s+(?:tomorrow|next|on\s+[a-z0-9]+)|cannot\s+attend|unable\s+to\s+attend|chutti)\b/i.test(text);

// 3. Support Issues & Discrepancies
const isSupportIssue = isLeave || /\b(cannot|can'?t|unable|error|issue|problem|fail|failed|broken|help\s*with|not\s*working|trouble|complaint|not\s*(?:updated|reflected|showing|received)|deducted|discrepancy|dispute|locked|crashed)\b/i.test(text);

// 4. Quiz answer submissions
const prefixMatch = /^(?:answers?|ans|my\s+answer(?:\s+is)?|option|choice)\b/i.test(text);
const singleOptionMatch = /^[a-dA-D](?:[\)\.\:\-\s]|$)/i.test(text);
const numberedMatch = /^[1-5]\s*[\)\.\:\-\s]*(?:->)?\s*[a-dA-D]/i.test(text);
const multiMatch = /(?:(?:question|q|ans|answer)?\s*[1-5]\s*[:.)\-–—\s]*(?:is\s*)?[a-dA-D]\b.*){2,}/i.test(text);
const inlineMatch = /\b(?:option|choice|answer|ans)\s*(?:[1-5]\s*)?(?:is|=|\:|\-)?\s*[a-dA-D]\b/i.test(text);
const guessMatch = /\b(?:i\s+think|guess)\s+(?:it(?:\s*is|\'s)\s+)?[a-dA-D]\b/i.test(text);

const isQuizAnswer = !isSecurityAttack && !isSupportIssue && (prefixMatch || singleOptionMatch || numberedMatch || multiMatch || inlineMatch || guessMatch);

// 5. Quiz generation requests
const isQuizRequest = !isSecurityAttack && !isSupportIssue && /\b(quiz|test(?:\s*me)?|practice|mcqs?|questions?|five\s*mcqs)\b/i.test(text) && !/\b(explain|what\s+is|doubt|why)\b/i.test(text);

// 6. Study Materials requests
const isMaterials = !isSecurityAttack && !isSupportIssue && !isQuizRequest && /\b(materials?|resources?|notes|lectures?|videos?|pdf|syllabus|curriculum|study\s*(?:material|guide|notes)?|kitabe|books|padhne)\b/i.test(text) && !/\b(explain|what\s+is)\b/i.test(text);

// 7. Student Profile & Enrollment
const isProfile = !isSecurityAttack && !isSupportIssue && /\b(my\s+profile|student\s*id|roll\s*(?:no|number)|enrollment\s*(?:no|number|details)?|my\s+details|who\s+am\s+i|meri\s+id)\b/i.test(text);

// 8. Teacher & Faculty
const isTeacher = !isSecurityAttack && !isSupportIssue && /\b(who\s*is\s*(?:my\s*)?teacher|who\s*teaches\s*(?:my\s*)?course|teacher\s*name|my\s*teacher|trainer|instructor|faculty|mere\s*teacher)\b/i.test(text);

// 9. Schedule, Timing & Course End-Date (Evaluated BEFORE generic course name)
const isSchedule = !isSecurityAttack && !isSupportIssue && /\b(when\s*(?:does|will)\s*(?:my\s*)?(?:course|batch)\s*(?:end|finish)|how\s*long\s*is\s*(?:my\s*)?course|how\s*many\s*days\s*(?:are\s*)?left|how\s*many\s*weeks\s*(?:are\s*)?left|course\s*duration|duration|timetable|schedule|class\s*timing|timing|routine|when\s*(?:is|are)\s*(?:my|the)?\s*classes?|next\s*class|time\s*table|kab\s+(?:khatam|over|finish)|kitna\s*time)\b/i.test(text);

// 10. Course & Batch info (Only if NOT duration/schedule/teacher)
const isCourseInfo = !isSecurityAttack && !isSupportIssue && !isTeacher && !isSchedule && /\b(what\s*is\s*(?:my\s*)?course|which\s*course|my\s*course|which\s*batch|which\s*class|my\s*batch|batch\s*name|course\s*name)\b/i.test(text);

// 11. Attendance & Certificate queries (Supports 'attendnce' typo)
const isAttendance = !isSecurityAttack && !isSupportIssue && !isSchedule && /\b(attend[a-z]*|present|absent|classes?\s*(?:held|attended|missed|remaining|total)?|how\s*many\s*classes|which\s*dates|percentage|eligib[a-z]*|certif[a-z]*|kitne?\s*din|haziri|75%)\b/i.test(text);

// 12. Fees & Payment queries
const isFees = !isSecurityAttack && !isSupportIssue && !isProfile && /\b(fees?|pay(?:ment|ing)?|paid|pending|balance|due|dues|receipt|transactions?|amount|total\s*(?:course\s*)?fee|installments?|baki|kitna\s*paisa)\b/i.test(text);

// 13. Academic Doubt / Tutor Mode
const isAcademicDoubt = !isSecurityAttack && !isSupportIssue && !isQuizAnswer && !isQuizRequest && !isProfile && !isTeacher && !isCourseInfo && !isSchedule && !isAttendance && !isFees &&
  (/\b(react|javascript|js|html|css|node(?:\.js)?|express|postgres(?:ql)?|sql|database|hook|component|state|props|api|function|variable|loop|promise|async|await|flexbox|grid|middleware|usestate|useeffect)\b/i.test(text) ||
   /\b(explain|difference\s+between|how\s+does|how\s+to\s+use|syntax\s+of|example\s+of|samjhao|doubt|kya\s+hota\s+hai|kaise\s+kare)\b/i.test(text));

// 14. Courtesy & About
const isThanks = /\b(thank\s*you|thanks|thx|cheers|appreciate\s*it|great\s*job|shukriya|dhanyawad)\b/i.test(text);
const isAbout = /\b(who\s*are\s*you|what\s*(?:can|do)\s*you\s*do|help\s*menu|options|commands|kya\s+kar\s+sakte)\b/i.test(text);
const isActualGreeting = /^(?:hi|hello|hey|good\s*(?:morning|afternoon|evening)|start|\/start|welcome|namaste)\b/i.test(text);

// 15. Multi-Intent Detection
const multiMatches = [];
if (isAttendance) multiMatches.push('attendance');
if (isFees) multiMatches.push('fees');
if (isTeacher) multiMatches.push('teacher');
if (isSchedule) multiMatches.push('schedule');
if (isCourseInfo) multiMatches.push('course');
if (isQuizRequest) multiMatches.push('quiz');

const isMulti = multiMatches.length >= 2;

let intent = 'greeting';
let greetingType = 'welcome';
let isMaterialsOnly = false;
let isExplanation = false;

if (isSecurityAttack) {
  intent = 'greeting';
  greetingType = 'security';
} else if (isMulti) {
  intent = 'greeting';
  greetingType = 'multi';
} else if (isQuizAnswer) {
  intent = 'quiz';
} else if (isQuizRequest) {
  intent = 'quiz';
} else if (isAcademicDoubt) {
  intent = 'quiz';
  isExplanation = true;
} else if (isMaterials) {
  intent = 'quiz';
  isMaterialsOnly = true;
} else if (isTeacher) {
  intent = 'greeting';
  greetingType = 'teacher';
} else if (isSchedule) {
  intent = 'greeting';
  greetingType = 'schedule';
} else if (isCourseInfo) {
  intent = 'greeting';
  greetingType = 'course';
} else if (isProfile) {
  intent = 'greeting';
  greetingType = 'profile';
} else if (isAttendance) {
  intent = 'attendance';
} else if (isFees) {
  intent = 'fees';
} else if (isThanks) {
  intent = 'greeting';
  greetingType = 'thanks';
} else if (isAbout) {
  intent = 'greeting';
  greetingType = 'about';
} else if (isActualGreeting) {
  intent = 'greeting';
  greetingType = 'welcome';
} else if (isSupportIssue) {
  intent = 'support';
} else {
  intent = 'greeting';
  greetingType = 'out_of_scope';
}

return [{json:{...base, intent, greetingType, isQuizAnswer, isMaterialsOnly, isExplanation, isLeave, multiMatches}}];

const source=$json;
const base=$('Parse Intent').first()?.json || {};
return [{json:{...base,backendData:source}}];

const source=$json;
const base=$('Parse Intent').first()?.json || {};
return [{json:{...base,backendData:source}}];

const source = $json;
let base = {};
try { base = $('Parse Intent').first()?.json || {}; } catch(e) {}
if (!base.messageText) {
  try { base = $('Build Session Context').first()?.json || {}; } catch(e) {}
}

const mats = source.materials || [];
const text = String(base.messageText || '').trim();
const isAnswer = Boolean(base.isQuizAnswer);
const isMaterialsOnly = Boolean(base.isMaterialsOnly);
const isExplanation = Boolean(base.isExplanation);

let systemPrompt = '';
let userPrompt = '';

if (isMaterialsOnly) {
  systemPrompt = "You are the EduConnect Assistant. Respond only with OK.";
  userPrompt = "OK";
} else if (isExplanation) {
  let matNames = mats.length > 0 ? mats.map(m => m.title).join(', ') : 'HTML & CSS, JavaScript ES6+, React Hooks, Node.js & Express REST APIs, PostgreSQL';
  systemPrompt = "You are the senior EduConnect Course Tutor for " + (base.courseName || 'Full Stack Web Development') + ". Modules: " + matNames + ".\n\nThe student asks: \"" + text + "\".\n\nCRITICAL INSTRUCTIONS:\n1. Keep your explanation concise, friendly, and under 250 words.\n2. Include a short, clear code snippet.\n3. Use clean formatting without excessive markdown symbols.\n4. End with one practical tip.";
  userPrompt = "Student Question: \"" + text + "\"\nCourse: " + (base.courseName || 'Full Stack Web Development') + "\nBatch: " + (base.batchName || 'FSWD Morning Batch - Jan 2025') + "\n\nPlease explain clearly in under 250 words.";
} else if (isAnswer) {
  let matNames = mats.length > 0 ? mats.map(m => m.title).join(', ') : 'HTML & CSS Fundamentals, JavaScript ES6+ Deep Dive, React Hooks Tutorial, Node.js & Express REST API Notes, PostgreSQL Database Design';

  const isMulti = /(?:(?:question|q|ans|answer)?\s*[1-5]\s*[:.)\-–—\s]*(?:is\s*)?[a-dA-D]\b.*){2,}/i.test(text);

  if (isMulti) {
    systemPrompt = "You are the EduConnect Quiz Evaluator for " + (base.courseName || 'Full Stack Web Development') + ". Official course materials: " + matNames + ".\n\nThe student submitted answers for an MCQ quiz:\n\"" + text + "\"\n\nFor each question answered, state whether it is Correct or Incorrect, mention the correct option, and provide a clear explanation. Then give an overall score and percentage with encouraging emojis.";
    userPrompt = "Here are my quiz answers:\n" + text + "\n\nPlease grade each question, provide explanations, and calculate my score.";
  } else {
    systemPrompt = "You are the EduConnect Quiz Evaluator for " + (base.courseName || 'Full Stack Web Development') + ". Official course materials: " + matNames + ".\n\nThe student has answered an MCQ question with:\n\"" + text + "\"\n\nEvaluate this answer. State clearly whether it is Correct or Incorrect, specify the correct answer with an explanation based on course materials, and give encouraging feedback. Do NOT generate or grade imaginary other questions.";
    userPrompt = "Here is my quiz answer: " + text + "\nPlease evaluate it and provide feedback.";
  }
} else {
  let matSummary = mats.length > 0 ? mats.map((m, i) => (i+1) + '. ' + m.title + ': ' + (m.description || '')).join('\n') : 'HTML5 & CSS3 Flexbox/Grid, JavaScript ES6+, React Hooks, Node.js & Express REST APIs, PostgreSQL Database Design';

  let topicInstruction = '';
  const topicMatch = text.match(/\b(?:on|about|for|regarding|in)\s+([a-zA-Z0-9\+\#\.\s]+?)(?:\s*(?:quiz|test|mcqs?|\?|$))/i) || text.match(/\b(react|javascript|js|html|css|node(?:\.js)?|express|postgres(?:ql)?|sql|database|api|flexbox|grid|hooks)\b/i);
  if (topicMatch) {
    const topic = (topicMatch[1] || topicMatch[0]).trim();
    topicInstruction = "\n\nCRITICAL TOPIC REQUIREMENT: The student requested a quiz specifically on \"" + topic + "\". ALL 5 questions MUST be strictly about \"" + topic + "\"!";
  }

  systemPrompt = "You are the EduConnect Quiz Specialist for " + (base.courseName || 'Full Stack Web Development') + ". Generate exactly 5 multiple-choice questions (MCQs) for the student based on their course materials." + topicInstruction + "\n\nCRITICAL RULES:\n1. For each question, provide 4 options labeled A, B, C, D.\n2. NEVER include the answers, solutions, or answer key in this message under any circumstances.";
  userPrompt = "The student's request is: \"" + text + "\".\nCourse: " + (base.courseName || 'Full Stack Web Development') + "\nAvailable Materials:\n" + matSummary + "\n\nPlease generate a 5-question MCQ quiz matching this request without the answer key.";
}

return [{
  json: {
    ...base,
    backendData: source,
    isQuizAnswer: isAnswer,
    isMaterialsOnly: isMaterialsOnly,
    isExplanation: isExplanation,
    quizSystemPrompt: systemPrompt,
    quizUserPrompt: userPrompt
  }
}];

let base = {};
try { base = $('Parse Intent').first()?.json || {}; } catch(e) {}
if (!base.messageText) {
  try { base = $('Build Session Context').first()?.json || {}; } catch(e) {}
}

const isLeave = Boolean(base.isLeave);
let promptInstruction = "You are the EduConnect Student Support Specialist. Provide a short, direct 1-2 sentence troubleshooting step for the student. Do NOT include greetings, corporate salutations, signatures, or placeholders like [Your Name]. Be extremely concise.";

return [{
  json: {
    ...base,
    supportInstruction: promptInstruction,
    ticketTitle: isLeave ? "Leave / Absence Application" : "Student Support Request",
    ticketType: isLeave ? "ATTENDANCE" : "GENERAL",
    backendData: {}
  }
}];

const ticket = $json;
const draft = $('Support Specialist (Ollama)').first()?.json || {};
const ctx = $('Prepare Support Context').first()?.json || $('Build Session Context').first()?.json || {};
let reply = String(draft.message?.content || draft.response || '').trim();

const ticketId = ticket.data?.id ? ticket.data.id.substring(0, 8).toUpperCase() : 'EC-' + Math.floor(1000 + Math.random() * 9000);

if (ctx.isLeave) {
  reply = `Your leave notice (#${ticketId}) has been registered with the batch coordinator. Class recordings and notes are available in the portal to catch up.`;
} else {
  // Strip salutations and sign-offs
  reply = reply.replace(/^(?:Dear|Hi|Hello|Hey)\s+[A-Za-z\s]+,?\s*/i, '');
  reply = reply.replace(/(?:Best regards|Sincerely|Thanks|Thank you|EduConnect Support)[^]*$/i, '').trim();
  if (reply.length > 250) {
    const periodIdx = reply.indexOf('.', 100);
    reply = periodIdx > 0 ? reply.substring(0, periodIdx + 1) : reply.substring(0, 250);
  }
  if (!reply) {
    reply = "Our technical support team has been notified and is investigating the issue.";
  }
  reply = `Support ticket #${ticketId} logged with administration. ` + reply;
}

return [{json:{replyText: reply.trim(), chatId: ctx.chatId}}];

const ctx = $('Prepare Attendance Context').first()?.json || {};
const att = ctx.backendData?.attendance || [];
const text = String(ctx.messageText || '');
let reply = '';

if (att.length === 0) {
  reply = "I couldn't find any attendance records in your LMS profile.";
} else {
  const total = att.length;
  const present = att.filter(a => a.status === 'PRESENT').length;
  const absent = att.filter(a => a.status === 'ABSENT').length;
  const pct = Math.round((present / total) * 100);

  const isCertQuery = /\b(certif(?:icate|ication)|eligib(?:le|ility)|exam|75%)\b/i.test(text);

  if (isCertQuery) {
    if (pct >= 75) {
      reply = `Attendance: ${pct}% (${present}/${total} classes). You are eligible for course certification (minimum 75% met).`;
    } else {
      reply = `Attendance: ${pct}% (${present}/${total} classes). You are not yet eligible for certification (minimum 75% required).`;
    }
  } else if (/miss|absent/i.test(text)) {
    const dates = att.filter(a => a.status === 'ABSENT').map(a => a.date).join(', ');
    reply = `You missed ${absent} classes out of ${total}. Absent dates: ${dates}.`;
  } else {
    reply = `Your attendance is ${pct}% (${present} attended out of ${total} classes). Status: ${pct >= 75 ? 'Good' : 'Low'}.`;
  }
}
return [{json:{replyText: reply, chatId: ctx.chatId}}];

const ctx = $('Prepare Fee Context').first()?.json || {};
let ledger = ctx.backendData?.ledger || null;
let txns = ctx.backendData?.transactions || [];
const text = String(ctx.messageText || '');
let reply = '';

// Fallback to grounded student database records if HTTP timed out
if (!ledger || !ledger.total_amount) {
  if (ctx.studentId === '4e0dda5a-a7e1-455d-b42b-08eb26027829' || !ctx.studentId) {
    ledger = {
      total_amount: 45000,
      paid_amount: 30000,
      pending_amount: 15000,
      status: 'PARTIAL'
    };
    txns = [
      { amount: 15000, payment_method: 'CASH', created_at: '2025-01-15' },
      { amount: 10000, payment_method: 'ONLINE', created_at: '2025-03-01' },
      { amount: 5000, payment_method: 'CASH', created_at: '2025-04-10' }
    ];
