text = text.replace(/[?&]utm_[a-zA-Z0-9_=-]+/gi, '');
text = text.replace(/n8n-internal\S*/gi, '');

// 2. Remove AI model preambles & conversational filler (Section 2 & 21)
text = text.replace(/^(?:Sure!?|Certainly!?|Of course!?|Here is the information you requested:?|As an AI language model[,\.]?|I'd be happy to help[,\.]?)\s*/i, '');
text = text.replace(/(?:\n+|^)(?:I hope this helps!?|Let me know if you need anything else!?|Feel free to reach out[^\n]*|Happy to help!?)\s*$/i, '');

// 3. Remove system / agent labels & XML tags
text = text.replace(/^(?:Assistant|Agent|Final answer):\s*/i, '');
text = text.replace(/<analysis>[\s\S]*?<\/analysis>/gi, '');
text = text.replace(/^```json[\s\S]*?```$/gi, '');

